// Shell Sort implementation
function shellSort(arr) {
  const n = arr.length;
  let gap = Math.floor(n / 2);

  while (gap > 0) {
    for (let i = gap; i < n; i++) {
      let key = arr[i];
      let j = i - gap;

      while (j >= 0 && arr[j] > key) {
        arr[j + gap] = arr[j];
        j -= gap;
      }

      arr[j + gap] = key;
    }
    gap = Math.floor(gap / 2);
  }

  return arr;
}

// Example usage
const arr = [23, 12, 1, 8, 34, 54, 2];
console.log('Original:', arr);
shellSort(arr);
console.log('Sorted:', arr); 
// [1, 2, 8, 12, 23, 34, 54]
